CREATE OR REPLACE FUNCTION public.fn_ca_f06_share_table_lane(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
BEGIN
  /* THE SHARED TABLE LANE OF A TOURNAMENT (2026-10-03). For per-table F06
     hand calls only: what f06_prefix does for one table and no users, with
     the tournament lane T(id) taken SHARED instead of exclusive and no lock
     on the tournament row (its status is written only under T(id) or G
     exclusive). Same order as f06_prefix and as
     fn_ca_share_settlement_lane_for_table: lease fence, G shared, T(id)
     shared, lease re-check, table row, seats. */
  IF p_table_id IS NULL THEN
    RAISE EXCEPTION 'F06_TABLE_LANE_NEEDS_A_TABLE' USING ERRCODE = '22023';
  END IF;
  PERFORM smarter_private.f06_authority(p_tournament_id, p_lease_generation);
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1', 0));
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1:' || p_tournament_id::text, 0));
  PERFORM smarter_private.f06_authority(p_tournament_id, p_lease_generation, false);
  PERFORM 1 FROM public.tables WHERE id = p_table_id FOR UPDATE;
  PERFORM s.id FROM public.table_seats s JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id AND s.table_id = p_table_id
   ORDER BY s.id FOR UPDATE OF s;
END
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_lock_tournament_seat_acquisition(p_tournament_id uuid, p_table_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_tournament_id uuid := p_tournament_id;
  v_table_id uuid := p_table_id;
  v_status text;
  v_max integer := 0;
  v_active integer := 0;
  v_started_at timestamptz; v_window_refusal text; v_window_tournament uuid;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','missing_user_id');
  END IF;
  -- THE DAILY WINDOW (20261103193545, 20261103222817): no NEW tournament entry
  -- 4:00 to 6:00 AM Chicago, none into a Spin or Sit & Go from 3:00 AM. A seat
  -- purchase names only its table, so the tournament is read from the table.
  -- A player already registered, playing or seated is never refused.
  v_window_tournament := COALESCE(p_tournament_id,(SELECT tb.tournament_id FROM public.tables tb WHERE tb.id=p_table_id));
  IF v_window_tournament IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id=v_window_tournament AND tp.user_id=p_user_id AND tp.status IN ('registered','playing'))
     AND NOT EXISTS(SELECT 1 FROM public.table_seats ts JOIN public.tables tb ON tb.id=ts.table_id
     WHERE tb.tournament_id=v_window_tournament AND ts.user_id=p_user_id AND ts.left_at IS NULL) THEN
   v_window_refusal := public.fn_daily_window_entry_refusal(v_window_tournament);
   IF v_window_refusal IS NOT NULL THEN RETURN jsonb_build_object('ok',false,'reason',v_window_refusal); END IF;
  END IF;
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id, p_table_id);
  PERFORM pg_advisory_xact_lock_shared(530093);
  IF EXISTS(SELECT 1 FROM public.ca_operator_floor_hold h JOIN public.ca_launch_operator_scopes m ON m.operation_id=h.operation_id JOIN public.tournaments t ON t.id=COALESCE(p_tournament_id,(SELECT tournament_id FROM public.tables WHERE id=p_table_id)) WHERE h.mode='park' AND (t.club_id=ANY(m.club_ids) OR t.union_id=ANY(m.club_ids)) AND NOT EXISTS(SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=t.id AND tp.user_id=p_user_id)) THEN
    RETURN jsonb_build_object('ok',false,'reason','operator_floor_parked');
  END IF;
  PERFORM pg_advisory_xact_lock_shared(530090,1);
  IF public.fn_ca_new_tournament_starts_blocked()
     AND COALESCE(p_tournament_id,(SELECT tournament_id FROM public.tables WHERE id=p_table_id)) IS NOT NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','operator_floor_parked');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('table_cap'), hashtext(p_user_id::text));
  PERFORM public.fn_lock_daily_mission_user(p_user_id);

  IF v_table_id IS NOT NULL THEN
    SELECT tb.tournament_id
    INTO v_tournament_id
    FROM public.tables tb
    WHERE tb.id = v_table_id
    FOR UPDATE;
  END IF;

  IF v_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;

  PERFORM 1
  FROM public.tournament_launch_receipts r
  WHERE r.tournament_id = v_tournament_id
  FOR UPDATE;

  SELECT
    upper(COALESCE(t.status::text, '')),
    COALESCE(t.max_players, 0),
    t.started_at
  INTO v_status, v_max, v_started_at
  FROM public.tournaments t
  WHERE t.id = v_tournament_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;

  PERFORM 1
  FROM public.tables tb
  WHERE tb.tournament_id = v_tournament_id
    AND COALESCE(tb.status, 'active') <> 'closed'
  ORDER BY tb.id
  FOR UPDATE;

  PERFORM 1
  FROM public.tournament_players tp
  WHERE tp.tournament_id = v_tournament_id
    AND tp.status::text IN ('registered', 'playing')
  ORDER BY tp.id
  FOR UPDATE;

  PERFORM 1
  FROM public.table_seats ts
  JOIN public.tables tb ON tb.id = ts.table_id
  WHERE tb.tournament_id = v_tournament_id
    AND ts.left_at IS NULL
  ORDER BY ts.id
  FOR UPDATE;

  SELECT COUNT(DISTINCT u.uid)::integer
  INTO v_active
  FROM (
    SELECT tp.user_id AS uid
    FROM public.tournament_players tp
    WHERE tp.tournament_id = v_tournament_id
      AND tp.status::text IN ('registered', 'playing')
      AND tp.user_id IS NOT NULL
    UNION
    SELECT ts.user_id AS uid
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
    WHERE tb.tournament_id = v_tournament_id
      AND COALESCE(tb.status, 'active') <> 'closed'
      AND ts.left_at IS NULL
      AND ts.user_id IS NOT NULL
  ) u;

  RETURN jsonb_build_object(
    'ok', true,
    'tournament_id', v_tournament_id,
    'table_id', v_table_id,
    'status', v_status,
    'max_players', v_max,
    'active_players', v_active,
    'started_at', v_started_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_register_for_tournament_with_ticket_for(p_tournament_id uuid, p_ticket_id uuid, p_beneficiary_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid:=p_beneficiary_id;
  v_value_ticket boolean:=false;
  v_diamond_value boolean:=false;
  v_diamond_receipt jsonb;
  v_t public.tournaments%ROWTYPE;
  v_ticket public.tournament_tickets%ROWTYPE;
  v_split record;
  v_username text;
  v_registration_id uuid;
  v_ledger_id uuid;
  v_tx_id uuid;
  v_entitlement_id uuid;
  v_resolved_club uuid;
  v_is_bounty boolean;
  v_late_open boolean:=false;
  v_start_chips integer:=0;
  v_seat jsonb;
  v_seat_reason text;
  v_players_before integer;
  v_wallet_rows_before bigint;
  v_wallet_rows_after bigint;
  v_rows integer;
  v_key text;
  v_ticket_use_token uuid:=gen_random_uuid();
  v_previous_ticket_use_token text:=
    current_setting('app.ca_satellite_ticket_use_token',true);
  v_escrow_before public.tournament_escrow%ROWTYPE;
  v_escrow_after public.tournament_escrow%ROWTYPE;
BEGIN
  IF p_tournament_id IS NULL OR p_ticket_id IS NULL OR v_uid IS NULL THEN
    RAISE EXCEPTION 'tournament, ticket and beneficiary ids are required'
      USING ERRCODE='22004';
  END IF;

  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  IF NOT pg_try_advisory_xact_lock_shared(530090,1) THEN
    RAISE EXCEPTION 'ticket_admission_platform_freeze_busy' USING ERRCODE='55P03';
  END IF;
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok',false,'reason','platform_frozen');
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  SELECT * INTO v_ticket FROM public.tournament_tickets tk
   WHERE tk.id=p_ticket_id FOR UPDATE;
  IF v_ticket.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_found');
  END IF;
  IF v_ticket.holder_id IS DISTINCT FROM v_uid THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_owned');
  END IF;
  IF v_ticket.redemption_mode IS DISTINCT FROM 'tournament_entry_only' THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_is_wallet_only');
  END IF;

  v_value_ticket:=public.fn_ca_satellite_value_ticket_marked(v_ticket.id);
  IF v_value_ticket THEN
    v_diamond_value:=public.fn_ca_assert_satellite_value_ticket(v_ticket.id)='diamonds';
    IF public.fn_poker_diamond_tournament(p_tournament_id) IS DISTINCT FROM v_diamond_value THEN
      RETURN jsonb_build_object('ok',false,'reason','ticket_asset_mismatch');
    END IF;
  ELSE
  IF v_ticket.source_refund_entitlement_id IS NOT NULL THEN
    SELECT count(*) INTO v_rows
      FROM public.tournament_refund_entitlements source_e
      JOIN public.chip_ledger issue_l
        ON issue_l.idempotency_key='tourney:'
             ||source_e.tournament_id::text
             ||':satellite-ticket-return:'||source_e.id::text
       AND issue_l.from_type='prize_liability'
       AND issue_l.from_entity_id=source_e.tournament_id
       AND issue_l.to_type='escrow' AND issue_l.to_entity_id=v_ticket.id
       AND issue_l.club_id=v_ticket.club_id AND issue_l.amount=source_e.gross
       AND issue_l.category='ticket_issue'
      LEFT JOIN LATERAL(SELECT COALESCE(sum(r.amount),0) amount,COALESCE(sum(r.fee_amount),0) fee,COALESCE(sum(r.loss_amount+r.active_amount),0) capital
       FROM public.ca_promo_ticket_principal_fee_returns r WHERE r.entitlement_id=source_e.id AND r.ticket_id=v_ticket.id AND r.issue_ledger_id=issue_l.id) returned ON true
     WHERE source_e.id=v_ticket.source_refund_entitlement_id
       AND v_ticket.source_satellite_award_place IS NULL
       AND source_e.user_id=v_uid
       AND source_e.entitlement_kind IN ('satellite_seat','tournament_ticket')
       AND source_e.gross=v_ticket.value+returned.amount
       AND greatest(0,source_e.refund_prize-returned.capital)=v_ticket.entry_prize
       AND source_e.refund_bounty-greatest(0,returned.capital-source_e.refund_prize)=v_ticket.entry_bounty
       AND source_e.refund_fee-returned.fee=v_ticket.entry_fee
       AND source_e.source_satellite_id=v_ticket.source_satellite_id
       AND source_e.tournament_id=v_ticket.source_tournament_id
       AND NOT EXISTS(
         SELECT 1 FROM public.tournament_refund_tranches tr
          WHERE tr.entitlement_id=source_e.id)
       AND (SELECT count(*) FROM public.chip_transactions issue_tx
             WHERE issue_tx.transaction_type='tournament_ticket_issue'
               AND issue_tx.club_id=v_ticket.club_id
               AND issue_tx.from_user_id IS NULL AND issue_tx.to_user_id=v_uid
               AND issue_tx.amount=source_e.gross
               AND issue_tx.metadata->>'ticket_id'=v_ticket.id::text
               AND issue_tx.metadata->>'entitlement_id'=source_e.id::text
               AND issue_tx.metadata->>'ledger_id'=issue_l.id::text)=1;
  ELSE
    -- A cap-blocked satellite winner never held a target registration, so its
    -- noncash ticket is sourced directly by the immutable satellite award.
    SELECT count(*) INTO v_rows
      FROM public.tournament_satellite_awards source_a
      JOIN public.tournament_satellite_settlements source_h
        ON source_h.tournament_id=source_a.tournament_id
      JOIN public.tournament_payouts source_p ON source_p.id=source_a.payout_id
      JOIN public.chip_ledger issue_l
        ON issue_l.idempotency_key=source_a.idempotency_key||':ticket_escrow'
       AND issue_l.from_type='prize_liability'
       AND issue_l.from_entity_id=source_a.tournament_id
       AND issue_l.to_type='escrow' AND issue_l.to_entity_id=v_ticket.id
       AND issue_l.club_id=v_ticket.club_id AND issue_l.amount=v_ticket.value
       AND issue_l.category='ticket_issue'
       AND issue_l.tournament_id=source_a.tournament_id
       AND issue_l.metadata->>'kind'='direct_satellite_entry_ticket'
       AND issue_l.metadata->>'ticket_id'=v_ticket.id::text
       AND issue_l.metadata->>'payout_id'=source_a.payout_id::text
       AND issue_l.metadata->>'satellite_target_id'=
             v_ticket.source_tournament_id::text
       AND issue_l.metadata->>'user_id'=source_a.user_id::text
       AND COALESCE(issue_l.metadata->>'position',issue_l.metadata->>'award_slot')=source_a.place::text
     WHERE source_a.tournament_id=v_ticket.source_satellite_id
       AND source_a.place=v_ticket.source_satellite_award_place
       AND source_a.user_id=v_uid
       AND source_a.delivery_kind='ticket'
       AND source_a.ticket_id=v_ticket.id
       AND source_a.amount=v_ticket.value
       AND source_a.payout_source='satellite_ticket'
       AND source_p.tournament_id=source_a.tournament_id
       AND source_p.user_id=source_a.user_id
       AND (source_p."position"=source_a.place OR source_h.receipt_version>=3)
       AND source_p.amount=source_a.amount
       AND source_p.source=source_a.payout_source
       AND source_p.idempotency_key=source_a.idempotency_key
       AND source_h.target_id=v_ticket.source_tournament_id
       AND source_h.ticket_cost=v_ticket.value
       -- A bounty target's seat ticket carries its bounty slice: the
       -- target's buy-in is the ticket's prize plus bounty (2026-10-16).
       AND source_h.target_buy_in=round(v_ticket.entry_prize+v_ticket.entry_bounty,2)
       AND source_h.target_fee=v_ticket.entry_fee
       AND p_tournament_id=v_ticket.source_tournament_id
       AND NOT EXISTS(
         SELECT 1 FROM public.wallet_credit_idempotency wallet_key
          WHERE wallet_key.key=source_a.idempotency_key)
       AND (SELECT count(*) FROM public.chip_transactions issue_tx
             WHERE issue_tx.transaction_type='tournament_ticket_issue'
               AND issue_tx.club_id=v_ticket.club_id
               AND issue_tx.from_user_id IS NULL AND issue_tx.to_user_id=v_uid
               AND issue_tx.amount=v_ticket.value
               AND issue_tx.metadata->>'ticket_id'=v_ticket.id::text
               AND issue_tx.metadata->>'source_tournament_id'=
                     p_tournament_id::text
               AND issue_tx.metadata->>'source_satellite_id'=source_a.tournament_id::text
               AND issue_tx.metadata->>'source_award_place'=source_a.place::text
               AND issue_tx.metadata->>'payout_id'=source_a.payout_id::text
               AND issue_tx.metadata->>'ledger_id'=issue_l.id::text
               AND issue_tx.metadata->>'idempotency_key'=
                     source_a.idempotency_key)=1;
  END IF;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament-entry ticket has no exact noncash issue evidence'
      USING ERRCODE='P0404';
  END IF;

  END IF;

  IF v_ticket.status='redeemed' THEN
    IF v_diamond_value THEN
      SELECT jsonb_build_object('ok',true,'replayed',true,'ticket_id',v_ticket.id,
        'registration_id',l.registration_id,'ledger_id',l.id,'asset','diamonds','wallet_chips_credited',0)
        INTO v_diamond_receipt FROM public.poker_diamond_tournament_ledger l
       WHERE l.idempotency_key='poker-value-ticket-entry:'||v_ticket.id::text
         AND l.tournament_id=p_tournament_id AND l.user_id=v_uid AND l.amount=v_ticket.value
         AND l.kind='entry' AND l.request->>'ticket_id'=v_ticket.id::text;
      RETURN coalesce(v_diamond_receipt,jsonb_build_object('ok',false,'reason','ticket_already_used'));
    END IF;
    SELECT count(*),min(e.id::text)::uuid,min(e.registration_id::text)::uuid
      INTO v_rows,v_entitlement_id,v_registration_id
      FROM public.tournament_refund_entitlements e
      JOIN public.tournament_players tp ON tp.id=e.registration_id
     WHERE e.source_ticket_id=v_ticket.id
       AND e.entitlement_kind='tournament_ticket'
       AND e.tournament_id=p_tournament_id
       AND e.user_id=v_uid
       AND tp.tournament_id=e.tournament_id AND tp.user_id=e.user_id;
    IF v_rows=1 AND v_entitlement_id IS NOT NULL
       AND v_registration_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok',true,'replayed',true,'ticket_id',v_ticket.id,
        'registration_id',v_registration_id,
        'entitlement_id',v_entitlement_id,'wallet_chips_credited',0);
    END IF;
    RETURN jsonb_build_object('ok',false,'reason','ticket_already_used');
  END IF;
  IF v_ticket.status<>'issued' THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_available');
  END IF;

  IF NOT public.fn_ca_tournament_is_unlimited(p_tournament_id)
     AND (lower(COALESCE(v_t.variant,''))='spin'
       OR (v_t.max_players IS NOT NULL
         AND v_t.max_players>0 AND v_t.max_players<=2)) THEN
    RETURN jsonb_build_object('ok',false,'reason','seat_first_variant');
  END IF;
  IF v_t.status='RUNNING' THEN
    v_late_open:=public.fn_tournament_late_registration_open(p_tournament_id)
                 AND NOT COALESCE(v_t.prize_pool_finalized,false);
  END IF;
  IF v_t.status NOT IN ('ANNOUNCED','REGISTERING') AND NOT v_late_open THEN
    RETURN jsonb_build_object('ok',false,'reason','registration_closed');
  END IF;
  IF COALESCE(v_t.prize_pool_finalized,false) THEN
    RETURN jsonb_build_object('ok',false,'reason','target_pool_finalized');
  END IF;
  IF public.fn_tournament_entry_cap_reached(p_tournament_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_full');
  END IF;
  IF EXISTS(SELECT 1 FROM public.tournament_players tp
             WHERE tp.tournament_id=p_tournament_id AND tp.user_id=v_uid) THEN
    RETURN jsonb_build_object('ok',false,'reason','already_registered');
  END IF;

  IF NOT v_diamond_value AND NOT EXISTS(
    SELECT 1 FROM public.club_members m
     WHERE m.club_id=v_ticket.club_id AND m.user_id=v_uid
       AND COALESCE(m.status,'active') IN ('active','approved')) THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_club_membership_inactive');
  END IF;
  IF v_t.union_id IS NULL AND v_t.club_id IS NOT NULL
     AND v_ticket.club_id IS DISTINCT FROM v_t.club_id THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_club_mismatch');
  END IF;
  IF v_t.union_id IS NOT NULL
     AND v_ticket.club_id IS DISTINCT FROM v_t.club_id AND NOT EXISTS(
    SELECT 1 FROM public.union_clubs uc
     WHERE uc.union_id=v_t.union_id AND uc.club_id=v_ticket.club_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_union_mismatch');
  END IF;
  IF v_diamond_value THEN
    IF NOT public.fn_ca_entry_scope_ok(v_uid,v_ticket.club_id) THEN
      RETURN jsonb_build_object('ok',false,'reason','ticket_arena_profile_unavailable');
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.ca_arena_settings a WHERE a.id=1 AND a.club_id=v_ticket.club_id AND a.tournaments_enabled) THEN
      RETURN jsonb_build_object('ok',false,'reason','diamond_tournaments_closed');
    END IF;
    v_resolved_club:=v_ticket.club_id;
  ELSE
    v_resolved_club:=public.fn_tournament_club_for_user(v_uid,p_tournament_id,v_ticket.club_id);
  END IF;
  IF v_resolved_club IS DISTINCT FROM v_ticket.club_id THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_source_club_unavailable');
  END IF;

  IF COALESCE(v_t.authorized_to_register,false)
     AND NOT EXISTS(
       SELECT 1 FROM public.tournament_registration_approvals a
        WHERE a.tournament_id=p_tournament_id AND a.user_id=v_uid)
     AND NOT public.is_club_admin(v_ticket.club_id,v_uid) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_authorized_to_register');
  END IF;
  IF COALESCE(v_t.is_vip_only,false)
     AND NOT EXISTS(
       SELECT 1 FROM public.profiles pr
        WHERE pr.id=v_uid AND COALESCE(pr.is_vip,false)
          AND (pr.vip_expires_at IS NULL OR pr.vip_expires_at>now()))
     AND NOT EXISTS(
       SELECT 1 FROM public.club_members m
        WHERE m.club_id=v_ticket.club_id AND m.user_id=v_uid
          AND m.role IN ('owner','co_owner','admin','agent')) THEN
    RETURN jsonb_build_object('ok',false,'reason','vip_only');
  END IF;

  v_is_bounty:=COALESCE(v_t.is_bounty,false)
            OR COALESCE(v_t.is_pko,false)
            OR COALESCE(v_t.is_mystery_bounty,false);
  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount,v_t.buy_in_fee,v_t.bounty_amount,v_is_bounty);
  IF v_split.charge IS NULL OR v_split.prize IS NULL
     OR v_split.bounty IS NULL OR v_split.rake IS NULL
     OR v_split.charge::text IN ('NaN','Infinity','-Infinity')
     OR v_split.prize::text IN ('NaN','Infinity','-Infinity')
     OR v_split.bounty::text IN ('NaN','Infinity','-Infinity')
     OR v_split.rake::text IN ('NaN','Infinity','-Infinity')
     OR v_split.charge<=0 OR v_split.prize<0
     OR v_split.bounty<0 OR v_split.rake<0
     OR v_split.charge IS DISTINCT FROM
          round(v_split.prize+v_split.bounty+v_split.rake,2)
     OR v_ticket.value IS DISTINCT FROM v_split.charge
     OR (NOT v_value_ticket AND (v_ticket.entry_prize IS DISTINCT FROM v_split.prize
       OR v_ticket.entry_bounty IS DISTINCT FROM v_split.bounty
       OR v_ticket.entry_fee IS DISTINCT FROM v_split.rake)) THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_entry_contract_mismatch');
  END IF;

  IF COALESCE(v_t.early_bird_enabled,false)
     AND now()<v_t.start_time AND COALESCE(v_t.early_bird_chips,0)>0 THEN
    v_start_chips:=v_t.early_bird_chips;
  END IF;
  SELECT COALESCE(NULLIF(p.display_name,''),NULLIF(p.username,''),'Player')
    INTO v_username FROM public.profiles p WHERE p.id=v_uid;
  v_username:=COALESCE(v_username,'Player');

  IF v_diamond_value THEN
    INSERT INTO public.tournament_players(tournament_id,user_id,username,chips,status,current_bounty,
      mystery_bounty_value,bounties_collected,bounty_winnings,club_id,is_satellite_qualifier,source_satellite_id)
    VALUES(p_tournament_id,v_uid,v_username,v_start_chips,'registered',0,0,0,0,v_ticket.club_id,true,v_ticket.source_satellite_id)
    RETURNING id INTO v_registration_id;
    v_diamond_receipt:=public.fn_ca_diamond_value_ticket_fund_entry(p_tournament_id,v_ticket.id,v_registration_id);
  ELSE
  PERFORM public.fn_ca_escrow_apply(p_tournament_id,'ticket admission prelock');
  SELECT * INTO v_escrow_before FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id FOR UPDATE;
  SELECT count(*) INTO v_players_before FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.status::text IN ('registered','playing');
  SELECT count(*) INTO v_wallet_rows_before
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=v_uid;
  IF v_escrow_before.tournament_id IS NULL
     OR v_escrow_before.enforced IS DISTINCT FROM true
     OR v_t.current_players IS DISTINCT FROM v_players_before
     OR v_t.prize_pool IS DISTINCT FROM v_escrow_before.prize_balance
     -- A running bounty event's bank is its pool less what knockouts have
     -- already paid from it, so a late ticket seat compares against that
     -- (2026-10-16), as both settlement authorities do.
     OR v_escrow_before.bounty_balance IS DISTINCT FROM
          round(COALESCE(v_t.bounty_pool,0)-COALESCE(v_t.bounty_pool_paid,0),2)
     OR v_t.total_rake IS DISTINCT FROM v_escrow_before.fee_balance THEN
    RAISE EXCEPTION 'ticket admission found divergent tournament escrow'
      USING ERRCODE='P0404';
  END IF;

  INSERT INTO public.tournament_players(
    tournament_id,user_id,username,chips,status,current_bounty,
    mystery_bounty_value,bounties_collected,bounty_winnings,
    club_id,is_satellite_qualifier,source_satellite_id)
  VALUES(
    p_tournament_id,v_uid,v_username,v_start_chips,'registered',
    v_split.bounty,0,0,0,v_ticket.club_id,true,v_ticket.source_satellite_id)
  RETURNING id INTO v_registration_id;

  v_key:='ticket:'||v_ticket.id::text||':tournament:'
         ||p_tournament_id::text||':entry';
  INSERT INTO public.chip_ledger(
    performed_by,from_type,from_entity_id,from_label,
    to_type,to_entity_id,to_label,amount,category,club_id,tournament_id,
    idempotency_key,settlement_id,actor_service,description,metadata,
    pre_from_balance,post_from_balance,pre_to_balance,post_to_balance)
  VALUES(
    v_uid,'escrow',v_ticket.id,'tournament entry ticket',
    'prize_liability',p_tournament_id,'tournaments escrow',
    v_ticket.value,'ticket_redeem',v_ticket.club_id,p_tournament_id,
    v_key,'ticket-entry:'||v_ticket.id::text,
    'fn_register_for_tournament_with_ticket',
    'Tournament-entry ticket committed to tournament admission',
    jsonb_build_object(
      'kind','tournament_entry_ticket_admission','ticket_id',v_ticket.id,
      'user_id',v_uid,'registration_id',v_registration_id,
      'source_tournament_id',v_ticket.source_tournament_id,
      'source_satellite_id',v_ticket.source_satellite_id,
      'entry_prize',v_split.prize,
      'entry_bounty',v_split.bounty,'entry_fee',v_split.rake),
    v_ticket.value,0,
    round(v_escrow_before.prize_balance+v_escrow_before.bounty_balance
          +v_escrow_before.fee_balance,2),
    round(v_escrow_before.prize_balance+v_escrow_before.bounty_balance
          +v_escrow_before.fee_balance+v_ticket.value,2))
  RETURNING id INTO v_ledger_id;

  PERFORM public.fn_ca_escrow_apply(
    p_tournament_id,'tournament-entry ticket admission',
    p_gross_in=>v_ticket.value,p_bounty_in=>v_split.bounty);
  IF v_split.rake>0 THEN
    INSERT INTO public.rake_records(
      hand_id,table_id,club_id,rake_amount,pot_size,num_players,
      bbj_contribution,is_tournament,tournament_id,source,metadata)
    VALUES(
      NULL,NULL,v_ticket.club_id,v_split.rake,v_ticket.value,1,
      0,true,p_tournament_id,'fn_register_for_tournament_with_ticket',
      jsonb_build_object(
        'kind','tournament_ticket_entry_fee','user_id',v_uid,
        'registration_id',v_registration_id,'ticket_id',v_ticket.id));
  END IF;

  UPDATE public.tournaments
     SET current_players=v_players_before+1,
         prize_pool=round(v_t.prize_pool+v_split.prize,2),
         bounty_pool=round(v_t.bounty_pool+v_split.bounty,2),
         total_rake=round(v_t.total_rake+v_split.rake,2),
         updated_at=now()
   WHERE id=p_tournament_id
     -- Before the start the canonical roster trigger has already counted
     -- the row inserted above. A RUNNING field is not counted on INSERT
     -- (20260922141704): this door publishes that count itself, as the
     -- wallet doors do. Expect exactly the state the trigger left.
     AND current_players IS NOT DISTINCT FROM CASE
       WHEN v_t.status IN ('ANNOUNCED','REGISTERING') THEN v_players_before+1
       ELSE v_players_before
     END
     AND prize_pool IS NOT DISTINCT FROM v_t.prize_pool
     AND bounty_pool IS NOT DISTINCT FROM v_t.bounty_pool
     AND total_rake IS NOT DISTINCT FROM v_t.total_rake;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'ticket admission tournament cache changed'
      USING ERRCODE='55000';
  END IF;

  END IF;

  INSERT INTO public.tournament_ticket_admission_authorizations(
    token,ticket_id,tournament_id,user_id,registration_id)
  VALUES(
    v_ticket_use_token,v_ticket.id,p_tournament_id,v_uid,v_registration_id);

  PERFORM set_config(
    'app.ca_satellite_ticket_use_token',v_ticket_use_token::text,true);
  UPDATE public.tournament_tickets
     SET status='redeemed',redeemed_at=transaction_timestamp()
   WHERE id=v_ticket.id AND status='issued';
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  PERFORM set_config(
    'app.ca_satellite_ticket_use_token',
    COALESCE(v_previous_ticket_use_token,''),true);
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament-entry ticket changed during admission'
      USING ERRCODE='55000';
  END IF;
  IF EXISTS(
    SELECT 1 FROM public.tournament_ticket_admission_authorizations a
     WHERE a.token=v_ticket_use_token) THEN
    RAISE EXCEPTION
      'tournament-entry ticket authorization was not consumed by admission'
      USING ERRCODE='P0404';
  END IF;

  IF NOT v_diamond_value THEN
  INSERT INTO public.tournament_refund_entitlements(
    tournament_id,user_id,entitlement_kind,charge_category,
    refund_wallet_club_id,gross,refund_prize,refund_bounty,refund_fee,
    source_ledger_id,registration_id,source_satellite_id,source_award_place,
    source_ticket_id,escrow_bucket,evidence_kind,created_at)
  VALUES(
    p_tournament_id,v_uid,'tournament_ticket','tournament_ticket',
    v_ticket.club_id,v_ticket.value,v_split.prize,
    v_split.bounty,v_split.rake,v_ledger_id,
    v_registration_id,v_ticket.source_satellite_id,NULL,v_ticket.id,
    'ticket_gross','atomic_tournament_ticket',transaction_timestamp())
  RETURNING id INTO v_entitlement_id;

  INSERT INTO public.chip_transactions(
    club_id,from_user_id,to_user_id,amount,transaction_type,notes,
    balance_after,metadata)
  VALUES(
    v_ticket.club_id,v_uid,NULL,v_ticket.value,
    'tournament_ticket_entry','Tournament-Entry Ticket Used',NULL,
    jsonb_build_object(
      'ticket_id',v_ticket.id,'holder_id',v_uid,
      'target_tournament_id',p_tournament_id,
      'registration_id',v_registration_id,
      'entitlement_id',v_entitlement_id,'ledger_id',v_ledger_id,
      'idempotency_key',v_key,'wallet_chips_credited',0))
  RETURNING id INTO v_tx_id;

  END IF;

  IF v_late_open THEN
    BEGIN
      v_seat:=public.fn_seat_late_registrant(p_tournament_id,v_uid);
    EXCEPTION WHEN SQLSTATE '55000' THEN
      PERFORM public.fn_ensure_late_registration_capacity(p_tournament_id,0);
      v_seat:=public.fn_seat_late_registrant(p_tournament_id,v_uid);
    END;
    v_seat_reason:=v_seat->>'reason';
    IF NOT COALESCE((v_seat->>'ok')::boolean,false)
       AND COALESCE(v_seat_reason,'')<>'already_seated_or_missing' THEN
      PERFORM public.fn_ensure_late_registration_capacity(p_tournament_id,0);
      v_seat:=public.fn_seat_late_registrant(p_tournament_id,v_uid);
      v_seat_reason:=v_seat->>'reason';
      IF NOT COALESCE((v_seat->>'ok')::boolean,false)
         AND COALESCE(v_seat_reason,'')<>'already_seated_or_missing' THEN
        RAISE EXCEPTION
          'Late ticket admission could not seat the player (%)',
          COALESCE(v_seat_reason,'unknown') USING ERRCODE='55000';
      END IF;
    END IF;
    -- The wake reasons are a closed list (fn_emit_tournament_manager_wake
    -- and tournament_manager_wakes_reason_check); the engine acts on
    -- 'late_registration'. A reason outside it rolled back every late
    -- ticket entry (20261012).
    PERFORM public.fn_emit_tournament_manager_wake(
      p_tournament_id,'late_registration');
  END IF;

  IF NOT v_diamond_value THEN
  SELECT * INTO v_escrow_after FROM public.tournament_escrow e
   WHERE e.tournament_id=p_tournament_id;
  SELECT count(*) INTO v_wallet_rows_after
    FROM public.wallet_transactions w
   WHERE w.related_entity_id=p_tournament_id AND w.user_id=v_uid;
  IF v_escrow_after.prize_balance IS DISTINCT FROM
       round(v_escrow_before.prize_balance+v_split.prize,2)
     OR v_escrow_after.bounty_balance IS DISTINCT FROM
       round(v_escrow_before.bounty_balance+v_split.bounty,2)
     OR v_escrow_after.fee_balance IS DISTINCT FROM
       round(v_escrow_before.fee_balance+v_split.rake,2)
     OR v_wallet_rows_after IS DISTINCT FROM v_wallet_rows_before THEN
    RAISE EXCEPTION 'ticket admission did not preserve exact noncash rails'
      USING ERRCODE='P0404';
  END IF;

  END IF;
  IF v_value_ticket THEN PERFORM public.fn_ca_assert_satellite_value_ticket(v_ticket.id); END IF;

  RETURN jsonb_build_object(
    'ok',true,'replayed',false,'ticket_id',v_ticket.id,
    'registration_id',v_registration_id,'entitlement_id',v_entitlement_id,
    'ledger_id',v_ledger_id,'transaction_id',v_tx_id,
    'ticket_value',v_ticket.value,'wallet_chips_credited',0,
    'prize_contribution',v_split.prize,
    'bounty_contribution',v_split.bounty,
    'fee_contribution',v_split.rake,'late_registration',v_late_open,
    'seat',v_seat)||CASE WHEN v_diamond_value THEN v_diamond_receipt ELSE '{}'::jsonb END;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_use_cashier_entry_ticket(p_tournament_id uuid, p_ticket_id uuid, p_beneficiary_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := p_beneficiary_id;
  v_t public.tournaments%ROWTYPE;
  v_tk public.tournament_tickets%ROWTYPE;
  v_bind public.tournament_ticket_entry_targets%ROWTYPE;
  v_split record;
  v_is_bounty boolean;
  v_is_horse boolean;
  v_before numeric;
  v_after_credit numeric;
  v_after numeric;
  v_context jsonb;
  v_setting text;
  v_prev_paying text := current_setting('app.ca_entry_paying_club', true);
  v_result jsonb;
  v_reason text;
  v_registration uuid;
  v_receipt uuid;
BEGIN
  IF p_tournament_id IS NULL OR p_ticket_id IS NULL OR v_uid IS NULL THEN
    RAISE EXCEPTION 'tournament, ticket and beneficiary ids are required'
      USING ERRCODE = '22004';
  END IF;

  -- The satellite ticket door's lock order: settlement lane, the shared
  -- admission lock, the admission contract, the tournament, then the ticket.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM pg_advisory_xact_lock_shared(530090,1);
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok',false,'reason','platform_frozen');
  END IF;
  SELECT * INTO v_t FROM public.tournaments t WHERE t.id = p_tournament_id FOR UPDATE;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  SELECT * INTO v_tk FROM public.tournament_tickets tk WHERE tk.id = p_ticket_id FOR UPDATE;
  IF v_tk.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_found');
  END IF;
  SELECT * INTO v_bind FROM public.tournament_ticket_entry_targets b
   WHERE b.ticket_id = v_tk.id;
  IF v_bind.ticket_id IS NULL THEN
    -- A value ticket has no event binding. Price it against the selected
    -- event now, under the same event/ticket locks, without persisting a bind.
    -- This cannot convert satellite/refund entitlements or Diamonds to chips.
    IF v_tk.redemption_mode IS DISTINCT FROM 'wallet_chips'
       OR v_tk.source_tournament_id IS NOT NULL
       OR v_tk.source_refund_entitlement_id IS NOT NULL
       OR public.fn_ca_tournament_unit_cents(p_tournament_id) IS DISTINCT FROM 1 THEN
      RETURN jsonb_build_object('ok',false,'reason','not_a_cashier_entry_ticket');
    END IF;
    v_is_bounty := COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
                OR COALESCE(v_t.is_mystery_bounty,false);
    SELECT * INTO v_split FROM public.fn_tournament_entry_split(
      v_t.buy_in_amount,v_t.buy_in_fee,v_t.bounty_amount,v_is_bounty);
    IF v_tk.value IS DISTINCT FROM v_split.charge THEN
      RETURN jsonb_build_object('ok',false,'reason','ticket_entry_contract_mismatch');
    END IF;
    v_bind.ticket_id:=v_tk.id;
    v_bind.tournament_id:=p_tournament_id;
    v_bind.holder_id:=v_tk.holder_id;
    v_bind.club_id:=v_tk.club_id;
    v_bind.issued_by:=v_tk.issued_by;
    v_bind.value:=v_tk.value;
    v_bind.entry_prize:=v_split.prize;
    v_bind.entry_bounty:=v_split.bounty;
    v_bind.entry_fee:=v_split.rake;
  END IF;
  IF v_tk.holder_id IS DISTINCT FROM v_uid OR v_bind.holder_id IS DISTINCT FROM v_uid THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_owned');
  END IF;
  IF v_bind.tournament_id IS DISTINCT FROM p_tournament_id THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_for_another_tournament');
  END IF;
  IF v_tk.redemption_mode IS DISTINCT FROM 'wallet_chips'
     OR v_tk.club_id IS DISTINCT FROM v_bind.club_id
     OR v_tk.issued_by IS DISTINCT FROM v_bind.issued_by
     OR v_tk.value IS DISTINCT FROM v_bind.value THEN
    RAISE EXCEPTION 'cashier entry ticket % does not match its binding', v_tk.id
      USING ERRCODE = 'P0404';
  END IF;

  IF v_tk.status = 'redeemed' THEN
    -- An ambiguous-response retry: the entry already happened.
    SELECT ct.id INTO v_receipt FROM public.chip_transactions ct
     WHERE ct.transaction_type = 'tournament_ticket_redeem'
       AND ct.metadata->>'ticket_id' = v_tk.id::text
       AND ct.metadata->>'reason' = 'tournament_entry'
       AND ct.metadata->>'target_tournament_id' = p_tournament_id::text
     LIMIT 1;
    SELECT tp.id INTO v_registration FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND tp.user_id = v_uid
     ORDER BY tp.registered_at DESC NULLS LAST LIMIT 1;
    IF v_receipt IS NOT NULL AND v_registration IS NOT NULL THEN
      RETURN jsonb_build_object('ok',true,'replayed',true,'ticket_id',v_tk.id,
        'registration_id',v_registration,'ticket_value',v_tk.value,
        'wallet_chips_credited',0);
    END IF;
    RETURN jsonb_build_object('ok',false,'reason','ticket_already_used');
  END IF;
  IF v_tk.status <> 'issued' THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_available');
  END IF;

  v_is_bounty := COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
              OR COALESCE(v_t.is_mystery_bounty,false);
  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount, v_t.buy_in_fee, v_t.bounty_amount, v_is_bounty);
  IF v_split.charge IS DISTINCT FROM v_bind.value
     OR v_split.prize IS DISTINCT FROM v_bind.entry_prize
     OR v_split.bounty IS DISTINCT FROM v_bind.entry_bounty
     OR v_split.rake IS DISTINCT FROM v_bind.entry_fee THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_entry_contract_mismatch');
  END IF;
  IF public.fn_tournament_club_for_user(v_uid, p_tournament_id, v_tk.club_id)
       IS DISTINCT FROM v_tk.club_id THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_source_club_unavailable');
  END IF;

  SELECT COALESCE(p.is_horse,false) INTO v_is_horse FROM public.profiles p WHERE p.id = v_uid;
  v_is_horse := COALESCE(v_is_horse,false);
  IF NOT v_is_horse AND auth.uid() IS DISTINCT FROM v_uid THEN
    -- A person is entered only by their own session; a horse has no browser
    -- and is entered by the engine (CLAUDE.md 10.5, the input device).
    RAISE EXCEPTION 'a cashier entry ticket is used by its own holder'
      USING ERRCODE = '42501';
  END IF;

  SELECT m.chip_balance INTO v_before FROM public.club_members m
   WHERE m.club_id = v_tk.club_id AND m.user_id = v_uid
     AND COALESCE(m.status,'active') IN ('active','approved')
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_club_membership_inactive');
  END IF;
  v_before := COALESCE(v_before,0);

  BEGIN
    -- (a) Escrow -> the holder's wallet in the ticket's club, journaled and
    --     receipted exactly as fn_redeem_tournament_ticket does it.
    SELECT jsonb_object_agg(k,COALESCE(current_setting(k,true),'')) INTO v_context
      FROM unnest(ARRAY['app.ledger_category','app.ledger_counterparty',
                        'app.ledger_counterparty_entity','app.ledger_tournament']) settings(k);
    PERFORM set_config('app.ledger_tournament','',true);
    PERFORM set_config('app.ledger_category','ticket_redeem',true);
    PERFORM set_config('app.ledger_counterparty','escrow',true);
    PERFORM set_config('app.ledger_counterparty_entity',v_tk.id::text,true);
    UPDATE public.club_members
       SET chip_balance = COALESCE(chip_balance,0) + v_tk.value, updated_at = now()
     WHERE club_id = v_tk.club_id AND user_id = v_uid
       AND COALESCE(status,'active') IN ('active','approved')
     RETURNING chip_balance INTO v_after_credit;
    FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
      PERFORM set_config(v_setting,v_context->>v_setting,true);
    END LOOP;
    IF v_after_credit IS DISTINCT FROM round(v_before + v_tk.value,2) THEN
      RAISE EXCEPTION 'cashier entry ticket % credit did not land exactly', v_tk.id
        USING ERRCODE = 'P0404';
    END IF;
    UPDATE public.tournament_tickets
       SET status = 'redeemed', redeemed_at = now()
     WHERE id = v_tk.id AND status = 'issued';
    INSERT INTO public.chip_transactions(
      club_id,from_user_id,to_user_id,amount,transaction_type,notes,
      balance_after,metadata)
    VALUES(
      v_tk.club_id,NULL,v_uid,v_tk.value,'tournament_ticket_redeem',
      'Tournament Ticket Used For Entry',v_after_credit,
      jsonb_build_object(
        'ticket_id',v_tk.id,'issuer_id',v_tk.issued_by,'holder_id',v_uid,
        'escrow_action','release_to_holder','reason','tournament_entry',
        'target_tournament_id',p_tournament_id,
        'holder_balance_after',v_after_credit))
    RETURNING id INTO v_receipt;
    INSERT INTO public.wallet_transactions(
      user_id,wallet_type,type,amount,category,description,balance_after)
    VALUES(
      v_uid,'PLAYER','credit',v_tk.value,'transfer',
      'Tournament Ticket Used For Entry',v_after_credit);

    -- (b) The ordinary entry door, paid from that same wallet.
    PERFORM set_config('app.ca_entry_paying_club',
      p_tournament_id::text||':'||v_uid::text||':'||v_tk.club_id::text, true);
    IF v_is_horse THEN
      v_result := public.fn_register_horse_for_tournament_before_atomic_lifecycle_gate(
        p_tournament_id, v_uid);
    ELSE
      v_result := public.fn_register_for_tournament_before_terminal_seat_gate(
        p_tournament_id, false);
    END IF;
    PERFORM set_config('app.ca_entry_paying_club', COALESCE(v_prev_paying,''), true);
    IF NOT COALESCE((v_result->>'ok')::boolean,false) THEN
      RAISE EXCEPTION USING ERRCODE = 'CT001',
        MESSAGE = COALESCE(NULLIF(v_result->>'reason',''),'registration_refused');
    END IF;

    -- (c) The wallet nets to zero exactly, in the ticket's club, or nothing
    --     happened.
    SELECT m.chip_balance INTO v_after FROM public.club_members m
     WHERE m.club_id = v_tk.club_id AND m.user_id = v_uid;
    SELECT tp.id INTO v_registration FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND tp.user_id = v_uid
       AND tp.id = (v_result->>'registration_id')::uuid;
    IF v_after IS DISTINCT FROM v_before OR v_registration IS NULL
       OR (v_result->>'cost')::numeric IS DISTINCT FROM v_tk.value THEN
      RAISE EXCEPTION 'cashier entry ticket % entry was not paid exactly from its own credit (% -> %)',
        v_tk.id, v_before, v_after USING ERRCODE = 'P0404';
    END IF;
  EXCEPTION WHEN SQLSTATE 'CT001' THEN
    v_reason := SQLERRM;
    PERFORM set_config('app.ca_entry_paying_club', COALESCE(v_prev_paying,''), true);
    RETURN jsonb_build_object('ok',false,'reason',v_reason,'ticket_id',v_tk.id);
  END;

  RETURN v_result || jsonb_build_object(
    'ok',true,'replayed',false,'ticket_id',v_tk.id,
    'registration_id',v_registration,'ticket_value',v_tk.value,
    'ticket_kind','cashier_entry_ticket','redeem_transaction_id',v_receipt,
    'wallet_chips_credited',0);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_f06_retain_hand_continuation(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_hand_number bigint, p_sequence bigint, p_payload text, p_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE h smarter_private.f06_hand_permits; c smarter_private.hand_continuations; v jsonb;
BEGIN
  PERFORM smarter_private.lock_hand_continuation_maintenance_lane();
  PERFORM public.fn_ca_f06_share_table_lane(p_tournament_id, p_lease_generation, p_table_id);
  IF public.fn_platform_frozen() THEN RAISE EXCEPTION 'PLATFORM_FROZEN'; END IF;
  IF p_sequence IS NULL OR p_sequence < 0 OR p_hand_number IS NULL OR p_hand_number < 1
     OR p_payload IS NULL OR octet_length(p_payload) > 1048576
     OR p_sha256 IS NULL OR p_sha256 !~ '^[a-f0-9]{64}$'
     OR encode(extensions.digest(p_payload, 'sha256'), 'hex') IS DISTINCT FROM p_sha256 THEN
    RAISE EXCEPTION 'HAND_CONTINUATION_INPUT_INVALID' USING ERRCODE = '22023';
  END IF;
  v := p_payload::jsonb;
  SELECT * INTO h FROM smarter_private.f06_hand_permits
   WHERE table_id = p_table_id AND hand_number = p_hand_number
     AND tournament_id = p_tournament_id FOR SHARE;
  IF h.permit_id IS NULL OR h.state <> 'reserved' OR h.evidence_id IS NOT NULL
     OR NOT EXISTS (SELECT 1 FROM public.tables tb WHERE tb.id = p_table_id
                     AND tb.tournament_id = p_tournament_id AND tb.f06_lifecycle = h.lifecycle)
     OR EXISTS (SELECT 1 FROM public.hand_atomic_commits a
                 WHERE a.table_id = p_table_id AND a.hand_number >= p_hand_number)
     OR EXISTS (SELECT 1 FROM public.hand_history hh
                 WHERE hh.table_id = p_table_id AND hh.hand_number >= p_hand_number)
     OR EXISTS (SELECT 1 FROM smarter_private.hand_submission_dispositions d
                 WHERE d.table_id = p_table_id AND d.hand_number = p_hand_number AND d.disposition = 'disposed') THEN
    RAISE EXCEPTION 'HAND_CONTINUATION_ORIGINAL_UNPROVEN' USING ERRCODE = '55000';
  END IF;
  IF v->>'version' IS DISTINCT FROM '1' OR v#>>'{batch,version}' IS DISTINCT FROM '1'
     OR v#>>'{batch,sequence}' IS DISTINCT FROM p_sequence::text
     OR v#>>'{original,tournament_id}' IS DISTINCT FROM h.tournament_id::text
     OR v#>>'{original,table_id}' IS DISTINCT FROM h.table_id::text
     OR v#>>'{original,hand_number}' IS DISTINCT FROM h.hand_number::text
     OR v#>>'{original,permit_id}' IS DISTINCT FROM h.permit_id::text
     OR v#>>'{original,lifecycle}' IS DISTINCT FROM h.lifecycle::text
     OR v#>>'{original,custody_id}' IS DISTINCT FROM h.custody_id::text
     OR v#>>'{original,lease_generation}' IS DISTINCT FROM h.generation::text
     OR jsonb_typeof(v->'seats') IS DISTINCT FROM 'array'
     OR jsonb_typeof(v#>'{batch,events}') IS DISTINCT FROM 'array'
     OR jsonb_typeof(v#>'{batch,engine}') IS DISTINCT FROM 'object'
     OR jsonb_typeof(v#>'{batch,controller}') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'HAND_CONTINUATION_BINDING_CHANGED' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(v->'seats') NOT BETWEEN 2 AND 9
     OR (SELECT count(DISTINCT x->>'user_id') FROM jsonb_array_elements(v->'seats') x)
          <> jsonb_array_length(v->'seats') THEN
    RAISE EXCEPTION 'HAND_CONTINUATION_ROSTER_INVALID' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO c FROM smarter_private.hand_continuations
   WHERE table_id = p_table_id AND hand_number = p_hand_number FOR UPDATE;
  IF FOUND THEN
    IF c.writer_generation IS DISTINCT FROM p_lease_generation
       OR c.original_generation IS DISTINCT FROM h.generation OR c.permit_id IS DISTINCT FROM h.permit_id
       OR c.payload::jsonb->'seats' IS DISTINCT FROM v->'seats' THEN
      RAISE EXCEPTION 'HAND_CONTINUATION_WRITER_FENCED' USING ERRCODE = '42501';
    END IF;
    IF c.sequence = p_sequence AND c.payload = p_payload AND c.payload_sha256 = p_sha256 THEN
      RETURN jsonb_build_object('ok', true, 'table_id', p_table_id, 'hand_number', p_hand_number::text,
        'sequence', p_sequence::text, 'sha256', p_sha256, 'writer_generation', c.writer_generation);
    END IF;
    IF p_sequence <> c.sequence + 1 THEN RAISE EXCEPTION 'HAND_CONTINUATION_SEQUENCE_CHANGED' USING ERRCODE = '55000'; END IF;
    UPDATE smarter_private.hand_continuations SET sequence = p_sequence, payload = p_payload,
      payload_sha256 = p_sha256, updated_at = clock_timestamp()
     WHERE table_id = p_table_id AND hand_number = p_hand_number;
  ELSE
    IF h.generation IS DISTINCT FROM p_lease_generation OR p_sequence <> 0
       OR v#>'{batch,events}' <> '[]'::jsonb THEN
      RAISE EXCEPTION 'HAND_CONTINUATION_ANCHOR_REQUIRED' USING ERRCODE = '55000';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(v->'seats') x
                WHERE NOT EXISTS (SELECT 1 FROM public.table_seats s
                  WHERE s.id::text = x->>'seat_id' AND s.table_id = p_table_id
                    AND s.user_id::text = x->>'user_id' AND s.left_at IS NULL
                    AND s.joined_at = (x->>'seat_joined_at')::timestamptz
                    AND s.stack = (x->>'stack_before')::numeric)) THEN
      RAISE EXCEPTION 'HAND_CONTINUATION_ROSTER_CHANGED' USING ERRCODE = '55000';
    END IF;
    INSERT INTO smarter_private.hand_continuation_dispositions(table_id, hand_number, disposition)
      VALUES(p_table_id, p_hand_number, 'retained') ON CONFLICT(table_id, hand_number) DO NOTHING;
    IF NOT EXISTS (SELECT 1 FROM smarter_private.hand_continuation_dispositions d
                   WHERE d.table_id = p_table_id AND d.hand_number = p_hand_number AND d.disposition = 'retained') THEN
      RAISE EXCEPTION 'HAND_CONTINUATION_ALREADY_DISPOSED' USING ERRCODE = '55000';
    END IF;
    INSERT INTO smarter_private.hand_continuations
      (table_id, hand_number, tournament_id, permit_id, original_generation, writer_generation,
       sequence, payload, payload_sha256)
    VALUES (p_table_id, p_hand_number, p_tournament_id, h.permit_id, h.generation,
      p_lease_generation, p_sequence, p_payload, p_sha256);
  END IF;
  RETURN jsonb_build_object('ok', true, 'table_id', p_table_id, 'hand_number', p_hand_number::text,
    'sequence', p_sequence::text, 'sha256', p_sha256, 'writer_generation', p_lease_generation);
END $function$

CREATE OR REPLACE FUNCTION public.fn_register_horse_for_tournament_before_terminal_gate(p_tournament_id uuid, p_user_id uuid, p_allow_wallet_charge boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_is_horse boolean;
  v_ticket_lookup jsonb;
  v_ticket_id uuid;
  v_ticket_registration_count integer:=0;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_allow_wallet_charge IS NULL THEN
    RAISE EXCEPTION 'tournament, horse and wallet authority are required'
      USING ERRCODE='22004';
  END IF;

  -- Ticket return, ticket admission and terminal settlement use this order.
  -- Holding both locks through the no-ticket decision prevents a concurrent
  -- unregister from issuing a ticket between selection and a wallet debit.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM pg_advisory_xact_lock_shared(530090,1);
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok',false,'reason','platform_frozen');
  END IF;

  SELECT is_horse INTO v_is_horse
    FROM public.profiles WHERE id=p_user_id;
  IF NOT COALESCE(v_is_horse,false) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_a_horse');
  END IF;

  -- An ambiguous-response retry arrives after the issued ticket has become
  -- redeemed. Recover that exact ticket id from the active immutable entry
  -- entitlement and let the admission core prove and replay the receipt.
  SELECT count(*),min(e.source_ticket_id::text)::uuid
    INTO v_ticket_registration_count,v_ticket_id
    FROM public.tournament_refund_entitlements e
    JOIN public.tournament_players tp ON tp.id=e.registration_id
   WHERE e.tournament_id=p_tournament_id
     AND e.user_id=p_user_id
     AND e.entitlement_kind='tournament_ticket'
     AND e.source_ticket_id IS NOT NULL
     AND tp.tournament_id=e.tournament_id
     AND tp.user_id=e.user_id
     AND tp.status::text IN ('registered','playing');
  IF v_ticket_registration_count>1 THEN
    RAISE EXCEPTION
      'horse ticket admission has multiple active immutable entitlements'
      USING ERRCODE='P0404';
  END IF;
  IF v_ticket_registration_count=1 AND v_ticket_id IS NOT NULL THEN
    RETURN public.fn_ca_register_for_tournament_with_ticket_for(
      p_tournament_id,v_ticket_id,p_user_id);
  END IF;

  v_ticket_lookup:=public.fn_ca_find_tournament_entry_ticket_for(
    p_tournament_id,p_user_id);
  IF COALESCE((v_ticket_lookup->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_ticket_lookup;
  END IF;
  v_ticket_id:=NULLIF(v_ticket_lookup->>'ticket_id','')::uuid;
  IF v_ticket_id IS NOT NULL THEN
    RETURN public.fn_ca_register_for_tournament_with_ticket_for(
      p_tournament_id,v_ticket_id,p_user_id);
  END IF;

  -- 20261015132042: a cashier ticket bound to this tournament enters the
  -- horse through the same door it enters a person (CLAUDE.md 10.5).
  v_ticket_lookup:=public.fn_ca_find_cashier_entry_ticket_for(
    p_tournament_id,p_user_id);
  v_ticket_id:=NULLIF(v_ticket_lookup->>'ticket_id','')::uuid;
  IF v_ticket_id IS NOT NULL THEN
    RETURN public.fn_ca_use_cashier_entry_ticket(
      p_tournament_id,v_ticket_id,p_user_id);
  END IF;

  IF p_allow_wallet_charge IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','hinted_tournament_ticket_no_longer_available');
  END IF;
  RETURN public.fn_register_horse_for_tournament_before_atomic_lifecycle_gate(
    p_tournament_id,p_user_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_register_horse_for_tournament(p_tournament_id uuid, p_user_id uuid, p_allow_wallet_charge boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_gate jsonb;
  v_paying uuid;
  v_result jsonb;
BEGIN
  -- 20261005224736 / A18 (horse_entry_funding, recorded 2026-10-05) and
  -- CLAUDE.md 10.5 (HORSES ARE PLAYERS - NO EXCEPTIONS). The owner's answer
  -- reads: "a horse funds its Diamond entry from its own balance, through the
  -- ordinary Diamond registration door a person uses." So this is no longer a
  -- blanket refusal resting on a Phase-9 assumption; it is that answer, READ
  -- AT CALL TIME. Changing the answer is one INSERT into ca_diamond_economics
  -- and no code change - 'own_balance' is never hard-coded as the decision.
  IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
    DECLARE
      v_horse_entry_funding text;
    BEGIN
      BEGIN
        v_horse_entry_funding :=
          public.fn_ca_diamond_economic_text('horse_entry_funding','all');
      EXCEPTION WHEN SQLSTATE 'P0D01' THEN
        -- No answer recorded. Refuse by name below rather than guess which
        -- funding the owner meant.
        v_horse_entry_funding := NULL;
      END;
      IF v_horse_entry_funding = 'funding_account' THEN
        -- House money, and there is no funding path for it yet. Refused by
        -- name, and the reason names the setting that produced the refusal.
        RETURN jsonb_build_object('ok',false,
          'reason','diamond_horse_funding_account_not_open',
          'horse_entry_funding',v_horse_entry_funding);
      ELSIF v_horse_entry_funding IS DISTINCT FROM 'own_balance' THEN
        RETURN jsonb_build_object('ok',false,
          'reason','diamond_horse_entry_funding_unrecognised',
          'horse_entry_funding',v_horse_entry_funding);
      END IF;
      -- 'own_balance': fall through. The horse takes the same seat-acquisition
      -- lock and the same registration chain a person takes, and pays from its
      -- own profiles.diamonds through the same Diamond door (10.5).
    END;
  END IF;
  v_gate:=public.fn_ca_lock_tournament_seat_acquisition(
    p_tournament_id,NULL,p_user_id);
  IF COALESCE((v_gate->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN v_gate;
  END IF;

  -- Owner November 1: free entries open six hours ahead; paid entries one hour ahead.
  -- The existing acquisition lock is held. Paid receipt retries remain valid;
  -- no ticket is redeemed and no wallet is charged on an early refusal.
  IF EXISTS (
    SELECT 1 FROM public.tournaments t
     WHERE t.id=p_tournament_id
       AND NOT public.fn_ca_horse_mtt_entry_purchase_window_open(
         t.format_contract,t.status,t.start_time,clock_timestamp(),
         t.buy_in_amount,t.buy_in_fee,t.free_buy)
  ) AND NOT EXISTS (
    SELECT 1 FROM public.tournament_players paid
     WHERE paid.tournament_id=p_tournament_id AND paid.user_id=p_user_id
       AND paid.status IN ('registered','playing')
  ) THEN
    RETURN jsonb_build_object('ok',false,'reason','horse_registration_not_open');
  END IF;

  -- A horse's purchase choice, not a human/platform capacity rule. Four
  -- unresolved tournament promises are enough when their duration is unknown.
  -- Paid target entries/chairs are honoured without making another purchase.
  IF EXISTS (SELECT 1 FROM public.profiles h WHERE h.id=p_user_id AND h.is_horse IS TRUE)
     AND NOT EXISTS (
       SELECT 1 FROM public.tournament_players paid
        WHERE paid.user_id=p_user_id AND paid.tournament_id=p_tournament_id
          AND paid.status IN ('registered','playing')
     )
     AND (SELECT count(DISTINCT promise.tournament_id)
            FROM public.tournament_players promise
            JOIN public.tournaments promised ON promised.id=promise.tournament_id
           WHERE promise.user_id=p_user_id
             AND promise.status IN ('registered','playing')
             AND upper(COALESCE(promised.status,'')) NOT IN ('COMPLETING','COMPLETED','CANCELLED')) >= 4 THEN
    RETURN jsonb_build_object('ok',false,'reason','horse_tournament_reservation_budget');
  END IF;

  /* THE WALLET THAT CAN PAY (2026-10-12), exactly as the person's door
     (fn_register_for_tournament) does it - CLAUDE.md 10.5, a horse is
     charged by the same rule. Only when this entry is paid from a wallet. */
  IF COALESCE(p_allow_wallet_charge, false) THEN
    v_paying := public.fn_ca_entry_paying_club(p_user_id, p_tournament_id);
    IF v_paying IS NOT NULL THEN
      PERFORM set_config('app.ca_entry_paying_club',
        p_tournament_id::text || ':' || p_user_id::text || ':' || v_paying::text, true);
    END IF;
  END IF;
  v_result := public.fn_register_horse_for_tournament_before_terminal_gate(
    p_tournament_id,p_user_id,p_allow_wallet_charge);
  PERFORM set_config('app.ca_entry_paying_club', '', true);
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_entry_paying_club(p_user_id uuid, p_tournament_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t record;
  v_charge numeric := 0;
  v_rebuy_need numeric := 0;
  v_addon_need numeric := 0;
  v_full_need numeric := 0;
  v_default uuid;
  v_balance numeric := 0;
  v_paying uuid;
BEGIN
  IF p_user_id IS NULL OR p_tournament_id IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT t.union_id, t.buy_in_amount, t.buy_in_fee, t.bounty_amount,
         t.rebuy_cost, t.addon_cost, t.is_rebuy, t.is_reentry, t.add_on_available,
         (COALESCE(t.is_bounty, false) OR COALESCE(t.is_pko, false)
          OR COALESCE(t.is_mystery_bounty, false)) AS is_bounty
    INTO v_t
    FROM public.tournaments t WHERE t.id = p_tournament_id;
  IF NOT FOUND OR v_t.union_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF public.fn_ca_tournament_unit_cents(p_tournament_id) = 100 THEN
    RETURN NULL;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND tp.user_id = p_user_id
  ) THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(s.charge, 0) INTO v_charge
    FROM public.fn_tournament_entry_split(
      v_t.buy_in_amount, v_t.buy_in_fee, v_t.bounty_amount, v_t.is_bounty) s;
  v_charge := GREATEST(COALESCE(v_charge, 0), 0);

  IF COALESCE(v_t.is_rebuy, false) OR COALESCE(v_t.is_reentry, false) THEN
    v_rebuy_need := GREATEST(COALESCE(NULLIF(v_t.rebuy_cost, 0), v_t.buy_in_amount, 0), 0);
  END IF;
  IF COALESCE(v_t.add_on_available, false) THEN
    v_addon_need := GREATEST(COALESCE(NULLIF(v_t.addon_cost, 0), v_t.buy_in_amount, 0), 0);
  END IF;

  -- Prefer a union wallet that can cover the entry AND at least one rebuy + add-on
  -- so the stamped entry wallet is never stranded on subsequent rebuy/add-on purchases.
  v_full_need := GREATEST(v_charge + v_rebuy_need + v_addon_need, v_charge, 0.01);

  v_default := public.fn_tournament_club_for_user(p_user_id, p_tournament_id, NULL);
  IF v_default IS NOT NULL THEN
    SELECT COALESCE(m.chip_balance, 0) INTO v_balance
      FROM public.club_members m
     WHERE m.user_id = p_user_id AND m.club_id = v_default
       AND m.status IN ('active', 'approved');
    IF COALESCE(v_balance, 0) >= v_full_need THEN
      RETURN NULL;
    END IF;
  END IF;

  v_paying := public.fn_ca_union_wallet_that_can_pay(p_user_id, v_t.union_id, v_full_need);
  IF v_paying IS NOT NULL THEN
    RETURN v_paying;
  END IF;

  IF v_charge > 0 THEN
    IF v_default IS NOT NULL AND COALESCE(v_balance, 0) >= v_charge THEN
      RETURN NULL;
    END IF;
    RETURN public.fn_ca_union_wallet_that_can_pay(p_user_id, v_t.union_id, v_charge);
  END IF;

  -- Free-Buy / freeroll fallback when no single wallet covers v_full_need:
  RETURN COALESCE(
    public.fn_ca_union_wallet_that_can_pay(
      p_user_id, v_t.union_id, GREATEST(v_rebuy_need, v_addon_need, 0.01)
    ),
    public.fn_ca_union_wallet_that_can_pay(p_user_id, v_t.union_id, 0.01)
  );
END
$function$
